<template>
  <view class="page">
    <view class="header"><view class="title">{{title}}</view><view class="sub">{{subtitle}}</view></view>
    <scroll-view scroll-x class="mode-tabs"><text v-for="x in modes" :key="x.value" :class="{active:mode===x.value}" @tap="changeMode(x.value)">{{x.label}}</text></scroll-view>

    <template v-if="mode==='operation'">
      <view class="range"><picker mode="date" :value="startDate" @change="startDate=$event.detail.value"><view>{{startDate||'开始日期'}}</view></picker><text>至</text><picker mode="date" :value="endDate" @change="endDate=$event.detail.value"><view>{{endDate||'结束日期'}}</view></picker><button size="mini" @tap="loadOperation">查询</button></view>
      <view class="grid"><view v-for="item in cards" :key="item.key" class="card"><view class="label">{{item.label}}</view><view class="value">{{format(data[item.key])}}</view></view></view>
      <view class="note">零售完成额按订单完成统计；退款和调拨退回按实际发生日扣减；历史区域和团队归属使用业务发生时快照。</view>
    </template>

    <template v-else-if="mode==='stockCheck'">
      <view class="note">盘点先固化账面快照。审核时如库存已经因正常业务发生变化，系统会拒绝使用过期盘点覆盖真实库存。</view>
      <button class="main-btn" :disabled="creating||!stockAccountId" @tap="createCheck">＋ 创建盘点快照</button>
      <view v-for="x in checks" :key="x.id" class="list-card" @tap="openCheck(x)"><view class="list-head"><strong>{{x.checkNo}}</strong><text :class="statusClass(x.status)">{{checkStatusText(x.status)}}</text></view><view class="list-meta"><text>快照 {{time(x.snapshotTime)}}</text><text>差异 {{x.differenceQuantity||0}}</text></view></view>
      <view v-if="checkLoaded&&!checks.length" class="empty">暂无盘点记录</view>
    </template>

    <template v-else>
      <view class="note">健康报告只整理本人真实血糖、饮食、运动和用药记录，不生成诊断、处方或虚构设备数据。</view>
      <view class="report-form"><view class="report-types"><text :class="{active:reportForm.reportType==='WEEKLY'}" @tap="reportForm.reportType='WEEKLY'">周报</text><text :class="{active:reportForm.reportType==='MONTHLY'}" @tap="reportForm.reportType='MONTHLY'">月报</text></view><view class="range"><picker mode="date" :value="reportForm.periodStart" @change="reportForm.periodStart=$event.detail.value"><view>{{reportForm.periodStart}}</view></picker><text>至</text><picker mode="date" :value="reportForm.periodEnd" @change="reportForm.periodEnd=$event.detail.value"><view>{{reportForm.periodEnd}}</view></picker></view><button class="main-btn" :disabled="generating" @tap="generateReport">{{generating?'生成中...':'基于真实记录生成报告'}}</button></view>
      <view v-for="x in reports" :key="x.id" class="list-card" @tap="openReport(x)"><view class="list-head"><strong>{{x.reportType==='WEEKLY'?'健康周报':'健康月报'}}</strong><text>{{date(x.periodStart)}} - {{date(x.periodEnd)}}</text></view><view class="report-metrics"><view><text>记录</text><strong>{{x.recordCount||0}}</strong></view><view><text>平均血糖</text><strong>{{x.averageGlucose==null?'--':x.averageGlucose}}</strong></view><view><text>高/低风险</text><strong>{{x.highCount||0}}/{{x.lowCount||0}}</strong></view></view></view>
      <view v-if="reportLoaded&&!reports.length" class="empty">暂无健康报告</view>
    </template>

    <view v-if="checkDetail" class="mask" @tap="checkDetail=null"><view class="sheet large" @tap.stop><view class="sheet-head"><strong>盘点详情</strong><text @tap="checkDetail=null">关闭</text></view><view v-for="x in checkDetail.items||[]" :key="x.id" class="check-item"><view><strong>{{x.productName||('商品'+x.productId)}}</strong><small>{{x.skuName||x.skuCode||x.skuId}}</small><text>账面 {{x.bookQuantity||0}}</text></view><view class="check-input"><input v-model.number="x.actualQuantity" type="number" :disabled="checkDetail.status!=='COUNTING'"/><button v-if="checkDetail.status==='COUNTING'" @tap="saveCount(x)">保存</button></view></view><button v-if="checkDetail.status==='COUNTING'" class="main-btn" @tap="submitCheck">提交审核</button></view></view>

    <view v-if="reportDetail" class="mask" @tap="reportDetail=null"><view class="sheet" @tap.stop><view class="sheet-head"><strong>{{reportDetail.reportType==='WEEKLY'?'健康周报':'健康月报'}}</strong><text @tap="reportDetail=null">关闭</text></view><view class="report-summary">{{reportDetail.summaryText||'该周期暂无可汇总记录。'}}</view><view class="report-detail-grid"><view><text>血糖记录</text><strong>{{reportDetail.glucoseCount||0}}</strong></view><view><text>平均值</text><strong>{{reportDetail.averageGlucose||'--'}}</strong></view><view><text>最低/最高</text><strong>{{reportDetail.minimumGlucose||'--'}}/{{reportDetail.maximumGlucose||'--'}}</strong></view><view><text>饮食/运动/用药</text><strong>{{reportDetail.dietCount||0}}/{{reportDetail.exerciseCount||0}}/{{reportDetail.medicineCount||0}}</strong></view></view><view class="medical">本报告仅用于健康记录整理，不构成医疗诊断。</view></view></view>
  </view>
</template>
<script>
import{getJkPersonalReport,getJkMyStock}from'@/api/jk.js';import{getJkStockCheckList,getJkStockCheckDetail,createJkStockCheck,countJkStockCheck,submitJkStockCheck,generateJkHealthReport,getJkHealthReportList,getJkHealthReportDetail}from'@/api/jkV31.js';
function d(v){return v.toISOString().slice(0,10)}
export default{data(){const end=new Date(),start=new Date();start.setDate(end.getDate()-6);return{mode:'operation',modes:[{label:'经营数据',value:'operation'},{label:'库存盘点',value:'stockCheck'},{label:'健康报告',value:'healthReport'}],startDate:'',endDate:'',data:{},stock:{},checks:[],checkLoaded:false,creating:false,checkDetail:null,reports:[],reportLoaded:false,generating:false,reportDetail:null,reportForm:{reportType:'WEEKLY',periodStart:d(start),periodEnd:d(end)},cards:[{key:'retailPerformanceAmount',label:'零售完成额'},{key:'retailRefundAmount',label:'当期零售退款'},{key:'retailNetPerformanceAmount',label:'零售净业绩'},{key:'retailOrderCount',label:'归属订单数'},{key:'transferInboundAmount',label:'调拨入库额'},{key:'transferReturnAmount',label:'调拨退回额'},{key:'stockAvailableQty',label:'可用库存'},{key:'stockFrozenQty',label:'冻结库存'},{key:'pendingCommissionAmount',label:'待结算佣金'},{key:'settledCommissionAmount',label:'已结算佣金'},{key:'availableFundAmount',label:'可提现资金'},{key:'withdrawingAmount',label:'提现中'},{key:'withdrawnAmount',label:'已提现'}]}},computed:{title(){return{operation:'个人经营中心',stockCheck:'库存盘点',healthReport:'健康报告'}[this.mode]},subtitle(){return{operation:'所有指标只统计本人或归属到本人的真实业务',stockCheck:'盘盈盘亏统一通过库存流水调整',healthReport:'仅汇总本人真实健康记录'}[this.mode]},stockAccountId(){const rows=this.stock.items||this.stock.records||[];return this.stock.stockAccountId||this.stock.accountId||(rows[0]&&rows[0].stockAccountId)||null}},onLoad(q){this.mode=['operation','stockCheck','healthReport'].includes(q.mode)?q.mode:'operation';this.loadMode()},methods:{changeMode(v){this.mode=v;this.loadMode()},loadMode(){if(this.mode==='operation')this.loadOperation();else if(this.mode==='stockCheck')this.loadChecks();else this.loadReports()},format(v){return v===undefined||v===null?'0':v},loadOperation(){uni.showLoading({title:'加载中'});getJkPersonalReport({startDate:this.startDate,endDate:this.endDate}).then(r=>this.data=(r&&r.data)||r||{}).finally(()=>uni.hideLoading())},loadChecks(){this.checkLoaded=false;Promise.all([getJkMyStock().catch(()=>({})),getJkStockCheckList({page:1,limit:100}).catch(()=>[])]) .then(([a,b])=>{this.stock=a.data||a||{};const x=b.data||b||[];this.checks=Array.isArray(x)?x:(x.list||x.records||[])}).finally(()=>this.checkLoaded=true)},createCheck(){if(!this.stockAccountId)return uni.showToast({title:'未找到当前库存账户',icon:'none'});this.creating=true;createJkStockCheck({requestNo:'CHECK-'+Date.now(),stockAccountId:this.stockAccountId,checkType:'FULL',remark:'小程序发起全盘'}).then(r=>{this.openCheck(r.data||r);this.loadChecks()}).finally(()=>this.creating=false)},openCheck(x){getJkStockCheckDetail(x.id).then(r=>this.checkDetail=r.data||r||null)},saveCount(x){if(x.actualQuantity==null||Number(x.actualQuantity)<0)return uni.showToast({title:'实盘数量不能小于0',icon:'none'});countJkStockCheck(this.checkDetail.id,{itemId:x.id,actualQuantity:Number(x.actualQuantity),remark:'小程序实盘录入'}).then(()=>uni.showToast({title:'已保存'}))},submitCheck(){if((this.checkDetail.items||[]).some(x=>x.actualQuantity==null))return uni.showToast({title:'请先录入全部实盘数量',icon:'none'});submitJkStockCheck(this.checkDetail.id,{requestNo:'SUBMIT-'+this.checkDetail.id+'-'+Date.now(),remark:'小程序提交审核'}).then(()=>{uni.showToast({title:'已提交审核'});this.checkDetail=null;this.loadChecks()})},loadReports(){this.reportLoaded=false;getJkHealthReportList({page:1,limit:100}).then(r=>{const x=r.data||r||[];this.reports=Array.isArray(x)?x:(x.list||x.records||[])}).finally(()=>this.reportLoaded=true)},generateReport(){this.generating=true;generateJkHealthReport({...this.reportForm,requestNo:'HEALTH-REPORT-'+Date.now()}).then(()=>{uni.showToast({title:'报告已生成'});this.loadReports()}).finally(()=>this.generating=false)},openReport(x){getJkHealthReportDetail(x.id).then(r=>this.reportDetail=r.data||r||null)},checkStatusText(v){return{COUNTING:'盘点中',SUBMITTED:'待审核',APPROVED:'已通过',REJECTED:'已驳回'}[v]||v},statusClass(v){return v==='APPROVED'?'success':v==='REJECTED'?'danger':'warning'},time(v){return v?String(v).replace('T',' ').slice(0,16):'--'},date(v){return v?String(v).slice(0,10):'--'}}};
</script>
<style scoped>.page{min-height:100vh;background:#f6f7f9;padding:24rpx;box-sizing:border-box}.header{padding:30rpx;border-radius:20rpx;background:linear-gradient(135deg,#18b997,#3b82f6);color:#fff}.title{font-size:36rpx;font-weight:600}.sub{margin-top:12rpx;font-size:23rpx;opacity:.88}.mode-tabs{margin-top:18rpx;white-space:nowrap}.mode-tabs text{display:inline-block;margin-right:12rpx;padding:13rpx 24rpx;border-radius:28rpx;background:#fff;color:#6f7d84;font-size:22rpx}.mode-tabs text.active{background:#10b981;color:#fff}.range{display:flex;align-items:center;gap:16rpx;margin-top:20rpx;padding:20rpx;border-radius:16rpx;background:#fff}.range picker{flex:1;color:#555}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:18rpx;margin-top:20rpx}.card,.list-card,.report-form{padding:24rpx;border-radius:16rpx;background:#fff}.label{color:#8a8f99;font-size:24rpx}.value{margin-top:12rpx;color:#1f2937;font-size:36rpx;font-weight:600}.note{margin-top:20rpx;padding:22rpx;border-radius:16rpx;background:#fff7e6;color:#8a5a00;font-size:22rpx;line-height:1.6}.main-btn{height:76rpx;margin-top:18rpx;border-radius:38rpx;background:#10b981;color:#fff;font-size:24rpx;line-height:76rpx}.main-btn[disabled]{opacity:.45}.list-card{margin-top:15rpx}.list-head,.list-meta{display:flex;align-items:center;justify-content:space-between}.list-head strong{font-size:24rpx}.list-head text,.list-meta{color:#7d898f;font-size:19rpx}.list-head .success{color:#10a981}.list-head .danger{color:#ef5b4c}.list-head .warning{color:#e6a23c}.list-meta{margin-top:12rpx}.empty{padding:60rpx 0;color:#929da2;text-align:center;font-size:22rpx}.report-form{margin-top:16rpx}.report-types{display:flex;gap:12rpx}.report-types text{flex:1;padding:14rpx;border-radius:12rpx;background:#f3f7f6;text-align:center;color:#78858b}.report-types text.active{background:#e9faf5;color:#10a981;font-weight:700}.report-metrics{display:flex;margin-top:16rpx}.report-metrics view{display:flex;flex:1;flex-direction:column;align-items:center;border-right:1rpx solid #edf1f0}.report-metrics view:last-child{border-right:0}.report-metrics text{color:#879299;font-size:18rpx}.report-metrics strong{margin-top:6rpx;color:#10a981;font-size:24rpx}.mask{position:fixed;z-index:100;inset:0;background:rgba(0,0,0,.43)}.sheet{position:absolute;right:0;bottom:0;left:0;max-height:80vh;overflow-y:auto;padding:25rpx 23rpx calc(26rpx + env(safe-area-inset-bottom));border-radius:28rpx 28rpx 0 0;background:#fff}.sheet-head{display:flex;justify-content:space-between}.sheet-head strong{font-size:29rpx}.sheet-head text{color:#7d898f}.check-item{display:flex;align-items:center;padding:16rpx 0;border-bottom:1rpx solid #edf1f0}.check-item>view:first-child{display:flex;min-width:0;flex:1;flex-direction:column;gap:5rpx}.check-item small,.check-item text{color:#849096;font-size:18rpx}.check-input{display:flex;align-items:center}.check-input input{width:100rpx;height:54rpx;border-radius:9rpx;background:#f4f7f6;text-align:center}.check-input button{height:54rpx;margin-left:8rpx;background:#10b981;color:#fff;font-size:18rpx;line-height:54rpx}.report-summary{margin-top:18rpx;padding:17rpx;border-radius:14rpx;background:#f3faf8;line-height:1.7}.report-detail-grid{display:grid;grid-template-columns:1fr 1fr;gap:12rpx;margin-top:17rpx}.report-detail-grid view{display:flex;flex-direction:column;gap:7rpx;padding:16rpx;border-radius:13rpx;background:#f7f9f9}.report-detail-grid text{color:#879299;font-size:18rpx}.medical{margin-top:17rpx;color:#9a6b1b;text-align:center;font-size:18rpx}</style>